files.system/blockMeshDict:
FoamFile
{
    format ascii;
    class dictionary;
    object blockMeshDict;
}
scale 1;
vertices
(
    (0 0 0)
    (0.5 0 0)
    (0.5 0.01 0)
    (0 0.01 0)
    (0 0 0.001)
    (0.5 0 0.001)
    (0.5 0.01 0.001)
    (0 0.01 0.001)
);
blocks
(
    hex (0 1 2 3 4 5 6 7) (150 40 1) simpleGrading (1 1 1)
);
boundary
(
    inlet
    {
        type patch;
        faces ((0 3 7 4));
    }
    outlet
    {
        type patch;
        faces ((1 2 6 5));
    }
    walls
    {
        type wall;
        faces ((0 1 5 4) (2 3 7 6));
    }
    frontAndBack
    {
        type empty;
        faces ((0 1 2 3) (4 5 6 7));
    }
);

files.constant/physicalProperties:
FoamFile
{
    format ascii;
    class dictionary;
    object physicalProperties;
}
viscosityModel constant;
nu 1.00380685e-06;

files.constant/momentumTransport:
FoamFile
{
    format ascii;
    class dictionary;
    object momentumTransport;
}
simulationType laminar;

files.system/fvSchemes:
FoamFile
{
    format ascii;
    class dictionary;
    object fvSchemes;
}
ddtSchemes
{
    default Euler;
}
gradSchemes
{
    default Gauss linear;
}
divSchemes
{
    default none;
    div(phi,U) Gauss linearUpwind grad(U);
}
laplacianSchemes
{
    default Gauss linear corrected;
}
interpolationSchemes
{
    default linear;
}
snGradSchemes
{
    default corrected;
}

files.system/fvSolution:
FoamFile
{
    format ascii;
    class dictionary;
    object fvSolution;
}
solvers
{
    p
    {
        solver GAMG;
        smoother DICGaussSeidel;
        tolerance 1e-09;
        relTol 0.01;
    }
    pFinal
    {
        $p;
        relTol 0;
    }
    U
    {
        solver smoothSolver;
        smoother symGaussSeidel;
        tolerance 1e-09;
        relTol 0.1;
    }
    UFinal
    {
        $U;
        relTol 0;
    }
}
PIMPLE
{
    nNonOrthogonalCorrectors 0;
    nCorrectors 2;
}

files.system/controlDict:
FoamFile
{
    format ascii;
    class dictionary;
    object controlDict;
}
solver incompressibleFluid;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 30.0;
deltaT 0.0625;
adjustTimeStep no;
writeControl timeStep;
writeInterval 80;
purgeWrite 0;
writeFormat ascii;
writePrecision 17;
writeCompression off;
timeFormat general;
timePrecision 14;
runTimeModifiable false;

files.0/U:
FoamFile
{
    format ascii;
    class volVectorField;
    object U;
}
dimensions [velocity];
internalField uniform (0.01 0 0);
boundaryField
{
    inlet
    {
        type fixedValue;
        value uniform (0.01 0 0);
    }
    outlet
    {
        type zeroGradient;
    }
    walls
    {
        type noSlip;
    }
    frontAndBack
    {
        type empty;
    }
}

files.0/p:
FoamFile
{
    format ascii;
    class volScalarField;
    object p;
}
dimensions [kinematicPressure];
internalField uniform 0;
boundaryField
{
